  // Brede, bløde former. Det eneste lag, der dækker meget af fladen.
  col = mix(col, u_colors[0], smoothstep(-0.30, 0.65, n1) * 0.75);

  // Lysere årer. Træder først frem, hvor støjen er høj, så de bliver
  // striber i det mørke frem for endnu et lag maling.
  col = mix(col, u_colors[1], smoothstep(0.15, 0.90, n2) * 0.30);

  // Sjældne mint-glimt. Lav vægt og høj tærskel med vilje: de skal være
  // noget, øjet finder, ikke noget, det møder.
  col = mix(col, u_colors[2], smoothstep(0.55, 0.95, n3) * 0.08);

